#!/usr/bin/env bash
#
# START modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
#
# device-info.sh — show what UPM build is installed on a (physical) device and
# whether its data is readable. Handy for diagnosing signature mismatches
# (compare the signer with the local debug keystore) before installing.
#
#   scripts/device-info.sh [SERIAL]
#
set -euo pipefail

APP_ID="com.u17od.upm"

command -v adb >/dev/null 2>&1 || { echo "[error] adb is not on PATH" >&2; exit 1; }

SERIAL="${1:-}"
if [[ -z "$SERIAL" ]]; then
    found="$(adb devices | awk '$1 !~ /^emulator-/ && $2 == "device" { print $1 }')"
    count="$(printf '%s\n' "$found" | grep -c '^[^[:space:]]' || true)"
    (( count == 1 )) || { echo "[error] need exactly one physical device (found $count) — pass SERIAL" >&2; exit 1; }
    SERIAL="$found"
fi

echo "== $SERIAL =="
adb -s "$SERIAL" shell getprop ro.product.model 2>/dev/null | tr -d '\r\n'; echo

echo "== apk =="
adb -s "$SERIAL" shell pm path "$APP_ID" 2>&1

echo "== version =="
adb -s "$SERIAL" shell dumpsys package "$APP_ID" 2>/dev/null \
    | grep -iE 'versionName|versionCode=|firstInstallTime|lastUpdateTime'

echo "== signer =="
adb -s "$SERIAL" shell dumpsys package "$APP_ID" 2>/dev/null \
    | grep -iE 'apkSigningVersion|signatures'

echo "== data (needs a debuggable build) =="
adb -s "$SERIAL" shell run-as "$APP_ID" ls -la files/ 2>&1 | head

echo "== local debug keystore =="
ls -la "$HOME/.android/debug.keystore" 2>&1
# END modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
